// Keep identity assets separate from scenery. These source rectangles are shared
// by the departure scene and the shore renderer; faces are never regenerated by UI.
export const CREW_FRAMES={
  woo:{file:'crew-woo-park-v5.png',frame:[230,5,420,1005]},
  park:{file:'crew-woo-park-v5.png',frame:[886,38,385,970]},
  han:{file:'crew-han-jeong-v1.png',frame:[230,14,440,990]},
  jeong:{file:'crew-han-jeong-v2.png',frame:[830,33,500,970]}
};
const images=new Map();
export function crewImage(id){
  const spec=CREW_FRAMES[id];
  if(!images.has(spec.file)){
    const image=new Image();image.src='assets/art/'+spec.file;images.set(spec.file,image);
  }
  return {image:images.get(spec.file),frame:spec.frame};
}
export function drawCaptain(canvas,id){
  const {image,frame}=crewImage(id);
  const draw=()=>{
    if(canvas.dataset.identity!==id||!canvas.isConnected)return;
    const c=canvas.getContext('2d'),[x,y,w,h]=frame;
    c.clearRect(0,0,canvas.width,canvas.height);
    const scale=Math.min(canvas.width/w,canvas.height/h);
    c.drawImage(image,x,y,w,h,(canvas.width-w*scale)/2,canvas.height-h*scale,w*scale,h*scale);
    canvas.dataset.ready=id;
  };
  canvas.dataset.identity=id;
  if(image.complete&&image.naturalWidth)draw();
  else image.addEventListener('load',draw,{once:true});
}
